import java.nio.file.Files;
import java.nio.file.Path;
import org.agentos.island.DotMatrixLoader;

/** Golden samples generated by the verbatim designer TypeScript, not the Java implementation. */
public class DotMatrixLoaderTest {
    public static void main(String[] args) throws Exception {
        int frames = 0;
        DotMatrixLoader.Pose p = new DotMatrixLoader.Pose();
        for (String row : Files.readAllLines(Path.of(args[0]))) {
            String[] values = row.split(",");
            DotMatrixLoader.thinking(Double.parseDouble(values[0]), p);
            for (int i = 0; i < 9; i++) {
                close(Double.parseDouble(values[1 + i]), p.opacity[i]);
                close(Double.parseDouble(values[10 + i]), p.scale[i]);
            }
            frames++;
        }
        double[] rest = {.92,.48,.24,.92,.8,.64,.92,.48,.24};
        DotMatrixLoader.rest(p);
        for (int i = 0; i < 9; i++) { close(rest[i], p.opacity[i]); close(1, p.scale[i]); }
        System.out.println("PASS: " + frames + " designer animation frames + reduced-motion pose");
    }
    private static void close(double expected, double actual) {
        if (Math.abs(expected - actual) > 1e-12) throw new AssertionError(expected + " != " + actual);
    }
}
